xml.Script:
        Clr[7] := '0000A0'; // clBlue
        Clr[5] := '008000'; // clGreen
        Clr[0] := '800080'; // clViolett
        Clr[1] := '2828FF'; // clLightBlue
        Clr[2] := '00FF00'; // clLightGreen
        Clr[3] := 'FF0080'; // clLightViolett
        Clr[6] := 'FF0000'; // clRed
        Clr[4] := 'FF6000'; // clOrange

        clYellow := 'FFFF00';
        clWhite  := 'FFFFFF';

        R  := 0.6;
        PV := 0.8; // vertical pillow
        H := R * 0.9;

        // every side divided into MxN faces
        N := 8;
        M := 32; // FacesPerRow

        function QInterpolate(xi, x1, y1, x2, y2, x3, y3);
        begin
            Result :=
                y1 * (xi - x2) * (xi - x3) / (x1 - x2) / (x1 - x3) +
                y2 * (xi - x3) * (xi - x1) / (x2 - x3) / (x2 - x1) +
                y3 * (xi - x1) * (xi - x2) / (x3 - x1) / (x3 - x2);
        end;

        for i := 0 to N do begin // vertical curve
            HZ[i] := H * (-1 + 2 / N * i);
            RZ[i] := R * QInterpolate(HZ[i], -H,PV, 0,1, H,PV)
        end;

        Id := 0;
        sUp := '';
        sDown := '';
        for j := 0 to M - 1 do begin
            A1 := 2 * Pi / M * j;
            cA1 := cos(A1);
            sA1 := sin(A1);
            sDown := IntToStr(Id) + ';' + sDown;
            for i := 0 to N do begin
                x[Id] := RZ[i] * cA1;
                y[Id] := RZ[i] * sA1;
                z[Id] := HZ[i];
                Inc(Id);
            end;
            sUp := sUp + IntToStr(Id - 1) + ';';
        end;
        D := R * PV / sqrt(2);

Macro.Script:
i1 := i * (N + 1) + Row;
i2 := (i + 1) mod M * (N + 1) + Row;
c := (i + dc) * 4 div M;
Inc(i);

Figure.Script:
Colors[0] := Clr[0];
Colors[1] := Clr[1];
Colors[2] := Clr[2];
Colors[3] := Clr[3];

Colors[0] := Clr[4];
Colors[1] := Clr[5];
Colors[2] := Clr[6];
Colors[3] := Clr[7];
Colors[4] := Clr[4];
